# parliament_crawler/spiders/parliament_spider.py
import scrapy
from ..items import LegalDocumentItem
import re
from datetime import datetime

class ParliamentSpider(scrapy.Spider):
    name = 'parliament'
    allowed_domains = ['parliament.gh']
    start_urls = ['https://www.parliament.gh/legal-documents/']
    
    def parse(self, response):
        # Extract document links
        for link in response.css('a::attr(href)').getall():
            if link.endswith('.pdf'):
                yield response.follow(link, self.parse_document)
        
        # Follow pagination
        next_page = response.xpath('//a[contains(text(), "Next")]/@href').get()
        if next_page:
            yield response.follow(next_page, self.parse)
    
    def parse_document(self, response):
        item = LegalDocumentItem()
        item['source_url'] = response.url
        
        # Extract metadata
        title = response.css('h1::text').get()
        if not title:
            title = response.xpath('//meta[@property="og:title"]/@content').get()
        item['title'] = title.strip() if title else 'Untitled Document'
        
        # Date extraction with multiple patterns
        date_text = response.css('span.date::text').get()
        if not date_text:
            date_text = response.xpath('//time/@datetime').get()
        if not date_text:
            date_text = response.xpath('//div[@class="metadata"]/text()').re_first(r'(\d{1,2} [A-Za-z]+ \d{4})')
        
        if date_text:
            try:
                item['date'] = datetime.strptime(date_text.strip(), '%d %B %Y').date()
            except ValueError:
                try:
                    item['date'] = datetime.fromisoformat(date_text.strip()).date()
                except ValueError:
                    self.logger.warning(f"Unrecognized date format: {date_text} on {response.url}")
                    item['date'] = None
        else:
            item['date'] = None
        
        # Document type detection
        if 'acts' in response.url:
            item['type'] = 'Act'
        elif 'bills' in response.url:
            item['type'] = 'Bill'
        elif 'committee-reports' in response.url:
            item['type'] = 'Committee Report'
        else:
            item['type'] = 'Legislative Instrument'
        
        return item

