# parliament_crawler/pipelines.py
import os
import sqlite3
import pdfplumber
from scrapy.pipelines.files import FilesPipeline
from scrapy.utils.project import get_project_settings

class ParliamentFilesPipeline(FilesPipeline):
    def file_path(self, request, response=None, info=None, item=None):
        # Create directory structure based on document type
        doc_type = item['type'].lower().replace(' ', '-')
        filename = os.path.basename(request.url)
        return f'legal_docs/{doc_type}/{filename}'

class TextConversionPipeline:
    def process_item(self, item, spider):
        pdf_path = item.get('pdf_path')
        if pdf_path and os.path.exists(pdf_path):
            text = ''
            with pdfplumber.open(pdf_path) as pdf:
                for page in pdf.pages:
                    text += page.extract_text() + '\n'
            
            # Create text file path
            text_path = pdf_path.replace('.pdf', '.txt')
            with open(text_path, 'w', encoding='utf-8') as f:
                f.write(text)
            
            item['text_path'] = text_path
        return item

class DatabaseStoragePipeline:
    def open_spider(self, spider):
        self.conn = sqlite3.connect('legal_documents.db')
        self.conn.execute('''
            CREATE TABLE IF NOT EXISTS legal_documents (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                title TEXT NOT NULL,
                date DATE,
                type TEXT,
                source_url TEXT UNIQUE,
                pdf_path TEXT,
                text_path TEXT
            )
        ''')
    
    def close_spider(self, spider):
        self.conn.close()
    
    def process_item(self, item, spider):
        try:
            self.conn.execute('''
                INSERT INTO legal_documents 
                (title, date, type, source_url, pdf_path, text_path)
                VALUES (?, ?, ?, ?, ?, ?)
            ''', (
                item['title'],
                item['date'],
                item['type'],
                item['source_url'],
                item.get('pdf_path'),
                item.get('text_path')
            ))
            self.conn.commit()
        except sqlite3.IntegrityError as e:
            spider.logger.warning(f"Duplicate document skipped: {item['source_url']} - {e}")
        
        return item

