# tests/test_spider.py
import unittest
from scrapy.crawler import CrawlerProcess
from scrapy.utils.project import get_project_settings
from parliament_crawler.spiders.parliament_spider import ParliamentSpider
from scrapy.http import TextResponse

class TestSpider(unittest.TestCase):
    def test_metadata_extraction(self):
        # Create mock HTML response
        body = '''
        <html>
            <head>
                <title>Sample Act</title>
                <meta property="og:title" content="Official Act Title"/>
            </head>
            <body>
                <h1>Act Title</h1>
                <span class="date">31 January 2023</span>
                <a href="/documents/acts/2023/act1.pdf">Download PDF</a>
            </body>
        </html>
        '''
        
        response = TextResponse(url='http://example.com', body=body, encoding='utf-8')
        spider = ParliamentSpider()
        
        # Simulate spider parsing
        results = spider.parse_document(response)
        item = next(results)
        
        self.assertEqual(item['title'], 'Act Title')
        self.assertEqual(item['date'].strftime('%Y-%m-%d'), '2023-01-31')
        self.assertEqual(item['type'], 'Act')
        self.assertTrue(item['source_url'].endswith('/documents/acts/2023/act1.pdf'))

