# tests/test_pipelines.py
import unittest
import os
import sqlite3
from parliament_crawler.pipelines import TextConversionPipeline, DatabaseStoragePipeline
from parliament_crawler.items import LegalDocumentItem

class TestPipelines(unittest.TestCase):
    def test_text_conversion(self):
        pipeline = TextConversionPipeline()
        item = LegalDocumentItem()
        item['pdf_path'] = 'test.pdf'
        
        # Create test PDF with text
        test_text = "This is a test document.\nWith multiple lines."
        with open(item['pdf_path'], 'w') as f:
            f.write(test_text)
        
        processed_item = pipeline.process_item(item, None)
        self.assertTrue(processed_item['text_path'].endswith('.txt'))
        self.assertTrue(os.path.exists(processed_item['text_path']))
        
        with open(processed_item['text_path'], 'r') as f:
            content = f.read()
            self.assertEqual(content.strip(), test_text)
        
        os.remove(item['pdf_path'])
        os.remove(processed_item['text_path'])
    
    def test_database_storage(self):
        pipeline = DatabaseStoragePipeline()
        pipeline.open_spider(None)
        
        item = LegalDocumentItem()
        item['title'] = 'Test Document'
        item['date'] = '2023-01-01'
        item['type'] = 'Test Type'
        item['source_url'] = 'http://example.com/test.pdf'
        item['pdf_path'] = 'test.pdf'
        item['text_path'] = 'test.txt'
        
        pipeline.process_item(item, None)
        
        conn = sqlite3.connect('legal_documents.db')
        cursor = conn.cursor()
        cursor.execute('SELECT * FROM legal_documents WHERE title = "Test Document"')
        result = cursor.fetchone()
        self.assertIsNotNone(result)
        self.assertEqual(result[1], 'Test Document')
        self.assertEqual(result[2], '2023-01-01')
        self.assertEqual(result[3], 'Test Type')
        self.assertEqual(result[4], 'http://example.com/test.pdf')
        self.assertEqual(result[5], 'test.pdf')
        self.assertEqual(result[6], 'test.txt')
        
        conn.close()
        os.remove('legal_documents.db')

